import{_ as t,o as e,c as l,a2 as r}from"./chunks/framework.Ca9F9Y59.js";const i="/k3gdb/assets/TAAF_%E6%B5%81%E7%A8%8B%E5%9B%BE.DkI1Uvol.png",o="/k3gdb/assets/AutoSD_%E7%A7%91%E5%AD%A6%E8%B0%83%E8%AF%95%E5%BE%AA%E7%8E%AF.Bog9fAJQ.png",h="/k3gdb/assets/TraceRepair_%E5%B7%A5%E4%BD%9C%E6%B5%81%E7%A8%8B.By0u2rnw.png",d="/k3gdb/assets/AutoFL_%E5%8F%AF%E8%A7%A3%E9%87%8A%E5%AE%9A%E4%BD%8D%E6%B5%81%E7%A8%8B.k7I3_QIR.png",m=JSON.parse('{"title":"《TAAF：知识图谱与大语言模型协同的执行轨迹抽象和分析框架》","description":"","frontmatter":{},"headers":[],"relativePath":"2026-10-29-LLM论文.md","filePath":"2026-10-29-LLM论文.md"}'),n={name:"2026-10-29-LLM论文.md"};function p(s,a,u,c,L,b){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="《taaf-知识图谱与大语言模型协同的执行轨迹抽象和分析框架》" tabindex="-1">《TAAF：知识图谱与大语言模型协同的执行轨迹抽象和分析框架》 <a class="header-anchor" href="#《taaf-知识图谱与大语言模型协同的执行轨迹抽象和分析框架》" aria-label="Permalink to &quot;《TAAF：知识图谱与大语言模型协同的执行轨迹抽象和分析框架》&quot;">​</a></h1><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>如何利用知识图谱和LLM，让开发者更容易理解和分析已经采集到的程序运行数据？</p><h2 id="核心思想" tabindex="-1">核心思想 <a class="header-anchor" href="#核心思想" aria-label="Permalink to &quot;核心思想&quot;">​</a></h2><p>不把海量原始 Trace 直接交给 LLM，而是先整理成具有时间信息和实体关系的结构化数据，再由 LLM 根据用户问题进行分析 在操作系统和大型软件中，程序执行会产生大量 Trace（执行轨迹），记录线程调度、CPU 执行、文件操作、系统调用等事件。 目前已经有 LTTng、Trace Compass 等工具支持采集和查询这些信息，但依然存在三个问题：</p><ol><li>数据量大：短时间运行就可能产生数千万甚至数亿条事件，无法全部输入 LLM。</li><li>事件关系复杂：一个分析问题可能涉及线程、CPU、文件以及多个时间区间，需要关联不同事件。</li><li>分析门槛高：开发者通常需要掌握操作系统内部机制，并编写专门的查询脚本才能得到答案。</li></ol><p>TAAF 就是希望开发者直接用自然语言提问，由系统完成结构化分析。</p><h2 id="taaf-的整体架构" tabindex="-1">TAAF 的整体架构 <a class="header-anchor" href="#taaf-的整体架构" aria-label="Permalink to &quot;TAAF 的整体架构&quot;">​</a></h2><p><img src="'+i+'" alt="TAAF架构"> 在第一层作者利用已有的State System，建立属性树和历史树把事件流转化为状态历史</p><p>第二层要做的是将状态转换为语义关系，知识图谱会把原本分散在时间状态中的实体、关系和数值组织成 LLM 更容易理解的证据结构</p><p>最终形成底层系统负责形成数据，上层 LLM 负责理解和解释的总体架构</p><h1 id="《autosd-基于大语言模型驱动科学调试的可解释自动化调试》" tabindex="-1">《AutoSD：基于大语言模型驱动科学调试的可解释自动化调试》 <a class="header-anchor" href="#《autosd-基于大语言模型驱动科学调试的可解释自动化调试》" aria-label="Permalink to &quot;《AutoSD：基于大语言模型驱动科学调试的可解释自动化调试》&quot;">​</a></h1><h2 id="问题-1" tabindex="-1">问题 <a class="header-anchor" href="#问题-1" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>如何让 LLM 调试程序的同时，提供由执行结果支持、便于开发者理解和验证的修复解释？ 传统的自动化程序修复已经能够自动生成补丁，可以告诉开发者应该怎么修改代码，却没有清楚地说明为什么这样修改，也就是应该提供能够帮助人类检查和理解补丁的解释。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模拟人类的科学调试过程，让llm通过“提出假设 → 运行实验 → 观察结果 → 得出结论”，完成可解释的自动化调试</p><h2 id="实现" tabindex="-1">实现 <a class="header-anchor" href="#实现" aria-label="Permalink to &quot;实现&quot;">​</a></h2><p><img src="'+o+'" alt="AutoSD"> 具体来说，AutoSD 有两个主要组成部分：</p><ul><li>LLM 负责决策： 分析代码、提出错误假设、生成实验、判断观察结果、提出修复方案。</li><li>真实调试器负责提供运行事实： 执行断点、检查变量、运行测试，并把实际结果返回给 LLM。</li></ul><p>提出了一种基于真实运行实验、能够解释调试过程的自动化调试方法。</p><p>但AutoSD需要反复调用 LLM 和调试器，生成补丁的平均耗时约为直接使用 LLM 的 4.66倍，而且实验主要处理单方法范围内的 Bug，没有证明能够可靠处理大型跨模块错误。</p><h1 id="《reval-基于llm的运行时行为推理》" tabindex="-1">《REval：基于LLM的运行时行为推理》 <a class="header-anchor" href="#《reval-基于llm的运行时行为推理》" aria-label="Permalink to &quot;《REval：基于LLM的运行时行为推理》&quot;">​</a></h1><h2 id="问题-2" tabindex="-1">问题 <a class="header-anchor" href="#问题-2" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>大语言模型能否真正理解程序运行时发生了什么，以及在连续推理过程中逻辑一致能否保持的问题</p><p>现有LLM对代码的评测往往重视输入和输出，但并不会充分检查程序执行中间发生的事情 作者把问题分成两个部分：</p><ul><li>1： 大模型推理程序运行时行为的能力如何？</li><li>2： 大模型在一系列推理任务中，逻辑是否一致？</li></ul><h2 id="方法-1" tabindex="-1">方法 <a class="header-anchor" href="#方法-1" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>通过把程序运行理解拆成四项任务，建立一套专门检验LLM是否真正理解程序执行过程的评测框架</p><table tabindex="0"><thead><tr><th>任务</th><th>模型需要推理的对象</th></tr></thead><tbody><tr><td>CCP</td><td>判断语句在实际运行中是否执行</td></tr><tr><td>PSP</td><td>预测执行某条语句后变量的值和类型</td></tr><tr><td>EPP</td><td>给定某条已经执行的语句，判断下一条执行语句</td></tr><tr><td>OP</td><td>程序最终输出</td></tr></tbody></table><p>除此之外，利用四项任务的依赖关系，提出增量一致性指标，用于衡量模型在推理任务中能否保持逻辑一致。</p><p>作者构建了一份评测数据集，并测试了多种代码大模型和通用大模型。</p><h2 id="结果与局限" tabindex="-1">结果与局限 <a class="header-anchor" href="#结果与局限" aria-label="Permalink to &quot;结果与局限&quot;">​</a></h2><p>测评发现，执行路径预测是最困难的任务之一，多数模型在增量一致性方面表现不佳</p><p>这说明在LLM调试过程，除了关注结果是否正确，还需验证是否真正理解了程序运行过程，同时在解释异步执行过程中，需要保持程序逻辑的前后一致</p><p>并且用到的程序主要是Python，构造评测数据需要选择特定语句、变量和执行位置，结果会受到题目构造方式影响。并且实验验证的主要是模型推理的功能，没考虑模型借助工具（GDB，调用栈）后的能力</p><p>最后表明，在利用LLM分析程序的过程中，不能只判断模型最终给出的异步关系是否正确，还需要检查它是否理解了运行证据，以及多次解释的逻辑能否保持一致，不能让模型通过推测补全。</p><h1 id="《tracerepair-基于trace引导的多策略辩论增强的llm的程序修复》" tabindex="-1">《TraceRepair：基于Trace引导的多策略辩论增强的LLM的程序修复》 <a class="header-anchor" href="#《tracerepair-基于trace引导的多策略辩论增强的llm的程序修复》" aria-label="Permalink to &quot;《TraceRepair：基于Trace引导的多策略辩论增强的LLM的程序修复》&quot;">​</a></h1><h2 id="问题-3" tabindex="-1">问题 <a class="header-anchor" href="#问题-3" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>如何把程序运行时产生的信息交给大模型来寻找 Bug 原因、提出修复方案？ 作者认为，许多现有 LLM 自动修复方法主要依赖源代码、报错信息和测试反馈，缺少足够细粒度的中间执行状态，难以可靠地解决复杂逻辑错误，而开发者遇到这种问题时，往往会进一步查看变量值、执行顺序和分支结果，论文尝试把这个过程系统化。</p><h2 id="方法-2" tabindex="-1">方法 <a class="header-anchor" href="#方法-2" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>1.先通过程序插桩记录关键变量的真实运行状态。</p><p>2.再让多个具有不同分析策略的修复智能体，基于同一份运行证据提出和审查修复假设。</p><p>3.最后实际编译和测试候选补丁，淘汰不符合运行事实或测试要求的方案</p><h2 id="实现-1" tabindex="-1">实现 <a class="header-anchor" href="#实现-1" aria-label="Permalink to &quot;实现&quot;">​</a></h2><p>观测运行 → 提出不同修复假设 → 交叉审查 → 实际执行验证 <img src="'+h+'" alt="AutoSD"> 在阶段2用到了三个智能体，分别从三个角度审查同一份信息，互相补充和批评，最后由负责裁决的LLM解决冲突，生成最终补丁。</p><ul><li>防御性策略：检查这个修复是否遗漏了可能导致程序再次出错的情况</li><li>因果性策略：分析错误是如何产生的，重点修复导致错误的计算逻辑</li><li>语义性策略：检查这个修改是否依旧符合设计意图</li></ul><p>同时给负责裁决的LLM设计了实际执行评分机制，来生成最终解决方案，再进入验证。 最终在实验中对程序修复有很好的效果，但为了避免模型可能在训练中见过某些公开 Bug 及其修复补丁，还格外构建了一个新的数据集，以及设计了消融实验证明这些环节都有贡献。</p><h2 id="局限" tabindex="-1">局限 <a class="header-anchor" href="#局限" aria-label="Permalink to &quot;局限&quot;">​</a></h2><p>它主要研究 Java 方法级修复，不是完整的软件工程自动化，运行轨迹的价值取决于能否观测到关键状态，插桩本身也可能失败。</p><h1 id="《autofl-基于llm的可解释性故障定位》" tabindex="-1">《AutoFL：基于LLM的可解释性故障定位》 <a class="header-anchor" href="#《autofl-基于llm的可解释性故障定位》" aria-label="Permalink to &quot;《AutoFL：基于LLM的可解释性故障定位》&quot;">​</a></h1><h2 id="问题-4" tabindex="-1">问题 <a class="header-anchor" href="#问题-4" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>怎么精确输出可疑代码位置以及解释错误原因？</p><ul><li>传统故障定位工具只能输出可疑代码位置、难以解释错误原因的问题</li><li>把整个项目交给大模型，可能会远超模型一次能有效处理的上下文规模，很容易忽略真正重要的上下文。</li></ul><p>作者想实现大模型不仅能给出可疑代码位置，还要解释错误是如何产生的，并通过工具调用自主查阅代码仓库，最终给出结果</p><h2 id="方法-3" tabindex="-1">方法 <a class="header-anchor" href="#方法-3" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给LLM一组可主动调用的代码检索工具，让模型决定需要检查的地方</p><h2 id="实现-2" tabindex="-1">实现 <a class="header-anchor" href="#实现-2" aria-label="Permalink to &quot;实现&quot;">​</a></h2><p><img src="'+d+'" alt="AutoSD"> 其中AutoFL的工具调用是通过预先定义的接口，从而让大模型在代码仓库中进行一次有工具支持的、逐步收集证据的调查</p><p>AutoFL 在一个程序中分析过程大致如下：</p><ol><li>先读取失败测试。</li><li>查询测试覆盖的类和方法。</li><li>获取关键方法的代码。</li><li>解释根因。</li><li>输出故障位置。</li></ol><p>为避免每次运行得到的故障位置不同，LLM会多次运行，再把不同轮次的预测合并起来进行可信度排名</p><h2 id="局限-1" tabindex="-1">局限 <a class="header-anchor" href="#局限-1" aria-label="Permalink to &quot;局限&quot;">​</a></h2><p>论文主要评估 Java 和 Python 项目，并依赖可复现的单元测试，它在定位故障源码上取得了不错的实验结果，但对故障的解释质量还不够稳定</p><p>未来在异步调试中，为了避免大量OS代码，可以让模型根据当前分析，决定下一步获取什么信息，根据问题逐步缩小调查范围</p>',64)])])}const q=t(n,[["render",p]]);export{m as __pageData,q as default};
